package io.github.finalparadox.client;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import io.github.finalparadox.entity.PumpkinHammerSwingEntity;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.block.BlockRenderDispatcher;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.inventory.InventoryMenu;import net.minecraft.world.level.block.Blocks;import net.minecraft.world.item.*;
public final class PumpkinHammerRenderer extends EntityRenderer<PumpkinHammerSwingEntity>{private final BlockRenderDispatcher blocks;private final net.minecraft.client.renderer.entity.ItemRenderer items;public PumpkinHammerRenderer(EntityRendererProvider.Context c){super(c);blocks=c.getBlockRenderDispatcher();items=c.getItemRenderer();shadowRadius=0;}@Override public ResourceLocation getTextureLocation(PumpkinHammerSwingEntity e){return InventoryMenu.BLOCK_ATLAS;}@Override public void render(PumpkinHammerSwingEntity e,float y,float p,PoseStack pose,MultiBufferSource b,int light){pose.pushPose();pose.mulPose(Axis.YP.rotationDegrees(-e.getYRot()));block(pose,b,light,.5,-.7,2,1);block(pose,b,light,.3,.2,2.2,.7F);block(pose,b,light,1.2,-.7,2,1);pose.pushPose();pose.translate(.55,-.6,1.15);pose.mulPose(Axis.XP.rotationDegrees(90));pose.mulPose(Axis.YP.rotationDegrees(45));pose.scale(2.2F,2.2F,2.2F);items.renderStatic(new ItemStack(Items.BAMBOO),ItemDisplayContext.FIXED,light,OverlayTexture.NO_OVERLAY,pose,b,e.level(),e.getId());pose.popPose();pose.popPose();super.render(e,y,p,pose,b,light);}private void block(PoseStack p,MultiBufferSource b,int l,double x,double y,double z,float s){p.pushPose();p.translate(x,y,z);p.mulPose(Axis.YP.rotationDegrees(45));p.scale(s,s,s);p.translate(-.5,-.5,-.5);blocks.renderSingleBlock(Blocks.PUMPKIN.defaultBlockState(),p,b,l,OverlayTexture.NO_OVERLAY);p.popPose();}}
